let array = [1, 2, 3, 4, 5, 6]

function binarySearch(array, val) {
    let min = 0
    let max = array.length - 1

    while (min <= max) { // <= 로 수정 (min < max 였던 부분)
        let middle = Math.floor((min + max) / 2)
        let currentEle = array[middle]

        if (currentEle === val) {
            return middle // 찾은 경우 인덱스 반환
        } else if (currentEle < val) {
            min = middle + 1 // 오른쪽 절반에서 탐색
        } else {
            max = middle - 1 // 왼쪽 절반에서 탐색
        }
    }

    return -1 // 찾지 못한 경우
}

console.log(binarySearch(array, 4)) // 결과: 3

